// Authoring source for reference/compat-catalog.json.
//
// Regexes live here as String.raw so they read as regexes, and `node tools/catalog/build.mjs`
// writes the JSON that the assessor, the tests and the skills consume. A test fails when the JSON
// and this file disagree, so neither can be edited alone.
//
// CLASSES
//   CLEAN    mechanical: a converter handles it and a reviewer only skims it.
//   PARTIAL  converts, but behaviour or performance can drift in an edge case; a human checks each use.
//   REVIEW   a design decision or hand rewrite on any PostgreSQL target.
//   BLOCKER  no supported equivalent on Azure Database for PostgreSQL flexible server. Remediation is a
//            redesign, an external service, or a different target. This is the only class that feeds
//            target eligibility, so it is used sparingly.
//
// WEIGHT is in cost units, where one unit is five minutes and 84 units are one person-day: the
// convention Ora2Pg uses. `origin` says where the number came from. `ora2pg-25.0:KEY` means the value
// is Ora2Pg's own score for KEY (lib/Ora2Pg/PLSQL.pm, %UNCOVERED_SCORE); `advisor` means this project
// assigned it, because Ora2Pg has no score for the construct or scores it too low to be useful here.
//
// `affectsClass: false` marks a semantic note that is true of nearly every object (for example the
// NULL behaviour of ||). It is counted and reported, but it does not move an object out of CLEAN.

const ROUTINES = ['PACKAGE_BODY', 'PACKAGE', 'PROCEDURE', 'FUNCTION', 'TRIGGER', 'TYPE_BODY'];
const SQLISH = [...ROUTINES, 'VIEW', 'MATERIALIZED_VIEW'];
const CODE = [...SQLISH, 'TYPE', 'JOB', 'PROGRAM', 'SCHEDULE', 'CHAIN', 'VPD_POLICY', 'FGA_POLICY', 'REFRESH_GROUP', 'QUEUE'];
const TABLES = ['TABLE', 'TYPE', 'MATERIALIZED_VIEW'];
const DDL = ['TABLE', 'INDEX', 'SEQUENCE', 'TYPE', 'CONSTRAINT', 'MATERIALIZED_VIEW', 'MATERIALIZED_VIEW_LOG', 'SYNONYM', 'DATABASE_LINK', 'CONTEXT'];
const ALL = [...new Set([...CODE, ...DDL, 'DIRECTORY', 'LIBRARY', 'OPERATOR', 'INDEXTYPE', 'DIMENSION', 'CLUSTER', 'PROFILE', 'ROLE', 'USER', 'TABLESPACE', 'JAVA_SOURCE', 'EDITION', 'PDB', 'LEGACY_JOB', 'WINDOW', 'JOB_CLASS', 'NETWORK_ACL', 'OTHER'])];

import { RESEARCH_ENTRIES } from './research-entries.mjs';

const entries = [];
function e(id, spec) {
  entries.push({
    id,
    category: spec.cat,
    name: spec.name,
    detect: spec.re ? spec.re.source : null,
    metric: spec.metric || null,
    flags: spec.flags || 'gi',
    view: spec.view || 'code',
    scope: spec.scope || CODE,
    classification: spec.cls,
    weight: spec.w,
    weightOrigin: spec.origin || 'advisor',
    affectsClass: spec.affects !== false,
    once: Boolean(spec.once),
    researchId: spec.rid || null,
    tag: spec.tag || null,
    labCase: spec.lab || null,
    postgres: spec.pg,
    extension: spec.ext || null,
    why: spec.why || null,
  });
}

const R = String.raw;

