// ---------------------------------------------------------------------------------------------
e('SQL-CONNECT-BY', { cat: 'sql-dialect', name: 'CONNECT BY hierarchical query', re: /\bCONNECT\s+BY\b/, cls: 'PARTIAL', w: 3, origin: 'ora2pg-25.0:CONNECT BY', lab: 'H-06',
  pg: 'WITH RECURSIVE; LEVEL, path and root columns are carried by hand', why: 'The basic shape converts mechanically. The pseudo-columns and loop detection do not.' });
e('SQL-CONNECT-BY-PSEUDO', { cat: 'sql-dialect', name: 'CONNECT BY pseudo-columns, NOCYCLE, ORDER SIBLINGS', re: /\b(?:SYS_CONNECT_BY_PATH|CONNECT_BY_ROOT|CONNECT_BY_ISLEAF|CONNECT_BY_ISCYCLE|NOCYCLE)\b|\bORDER\s+SIBLINGS\s+BY\b/, cls: 'REVIEW', w: 4, lab: 'H-06',
  pg: 'Carry path, root and depth through the recursive term; add CYCLE (PG 14+) or a visited-path guard', why: 'Oracle detects cycles with NOCYCLE. PostgreSQL recurses until it runs out of memory unless the query guards itself.' });
e('SQL-ROWNUM', { cat: 'sql-dialect', name: 'ROWNUM', re: /\bROWNUM\b/, cls: 'PARTIAL', w: 1, origin: 'ora2pg-25.0:ROWNUM', lab: 'H-30', tag: 'semantic',
  pg: 'ROW_NUMBER() OVER (...) or LIMIT, never both interchangeably', why: 'ROWNUM is assigned before ORDER BY. A naive LIMIT conversion returns a different set of rows.' });
e('SQL-OUTER-JOIN-PLUS', { cat: 'sql-dialect', name: 'Oracle (+) outer join', re: /\(\s*\+\s*\)/, cls: 'PARTIAL', w: 2, origin: 'ora2pg-25.0:OUTER JOIN', lab: 'H-32',
  pg: 'ANSI LEFT/RIGHT JOIN', why: 'Mechanical for two tables. Predicates on the outer side move between ON and WHERE and change the result.' });
e('SQL-MERGE', { cat: 'sql-dialect', name: 'MERGE INTO', re: /\bMERGE\s+INTO\b/, cls: 'CLEAN', w: 3, origin: 'ora2pg-25.0:MERGE INTO', lab: 'H-07',
  pg: 'MERGE (PG 15+) or INSERT ... ON CONFLICT DO UPDATE', why: 'Syntax survives on PG 15+. Concurrency behaviour under load differs and needs a test.' });
e('SQL-MERGE-DELETE-CLAUSE', { cat: 'sql-dialect', name: 'MERGE with DELETE WHERE', re: /\bDELETE\s+WHERE\b/, cls: 'REVIEW', w: 2, lab: 'H-07',
  pg: 'WHEN MATCHED AND <cond> THEN DELETE (PG 15+)', why: 'The conditional DELETE inside the UPDATE branch has a different shape in PostgreSQL.' });
e('SQL-DUAL', { cat: 'sql-dialect', name: 'FROM DUAL', re: /\bFROM\s+DUAL\b/, cls: 'CLEAN', w: 0.05, pg: 'Drop the FROM clause (or use orafce dual)', ext: 'orafce', affects: false });
e('SQL-NVL', { cat: 'sql-dialect', name: 'NVL / NVL2 / DECODE', re: /\b(?:NVL2?|DECODE)\s*\(/, cls: 'CLEAN', w: 0.1, lab: 'H-31', affects: false,
  pg: 'COALESCE / CASE; orafce supplies nvl, nvl2 and decode', ext: 'orafce', why: 'DECODE treats NULL = NULL as a match and CASE does not. A converter that emits plain CASE changes results.' });
e('SQL-DECODE-NULL-KEY', { cat: 'semantics', name: 'DECODE with a NULL search value', re: /\bDECODE\s*\(\s*[^,()]+(?:\([^()]*\))?[^,()]*,\s*NULL\s*,/, scope: SQLISH, cls: 'PARTIAL', w: 1, lab: 'H-31', rid: 'SQL-15',
  pg: 'CASE WHEN x IS NULL THEN ... END. DECODE treats two NULLs as equal; a simple CASE x WHEN NULL never matches. Whether the orafce decode() keeps the Oracle behaviour is not verified',
  why: 'A converter that emits a simple CASE silently changes the result for NULL input.' });
e('SQL-MINUS', { cat: 'sql-dialect', name: 'MINUS', re: /\bMINUS\b/, cls: 'CLEAN', w: 0.1, pg: 'EXCEPT', affects: false });
e('SQL-LISTAGG', { cat: 'sql-dialect', name: 'LISTAGG', re: /\bLISTAGG\s*\(/, cls: 'PARTIAL', w: 1, pg: 'string_agg(expr, sep ORDER BY ...)', why: 'ON OVERFLOW TRUNCATE has no equivalent. WITHIN GROUP ordering moves into the aggregate.' });
e('SQL-ANALYTIC-ORACLE-ONLY', { cat: 'sql-dialect', name: 'KEEP (DENSE_RANK), RATIO_TO_REPORT, NTH_VALUE FROM LAST', re: /\bKEEP\s*\(\s*DENSE_RANK\b|\bRATIO_TO_REPORT\b|\bNTH_VALUE\b[^;]{0,200}\bFROM\s+LAST\b/, cls: 'PARTIAL', w: 1.5, lab: 'H-08',
  pg: 'FIRST_VALUE/LAST_VALUE with a frame; x / SUM(x) OVER (); a reversed ORDER BY', why: 'Ordinary window functions carry over unchanged. These three are Oracle-only spellings.' });
e('SQL-PIVOT', { cat: 'sql-dialect', name: 'PIVOT / UNPIVOT', re: /\b(?:UN)?PIVOT\s*(?:XML\s*)?\(/, cls: 'REVIEW', w: 4, pg: 'FILTER aggregates, crosstab() from tablefunc, or LATERAL VALUES', ext: 'tablefunc', why: 'PostgreSQL has no PIVOT keyword. The column list must be static or the query becomes dynamic SQL.' });
e('SQL-MODEL-CLAUSE', { cat: 'sql-dialect', name: 'MODEL clause', re: /\bMODEL\s+(?:DIMENSION\s+BY|PARTITION\s+BY|MEASURES|RETURN\s+(?:UPDATED|ALL)\s+ROWS)\b/, cls: 'BLOCKER', w: 20, pg: 'None. Rewrite as recursive CTE, window functions or PL/pgSQL', why: 'Spreadsheet-style MODEL queries have no PostgreSQL counterpart.' });
e('SQL-FLASHBACK-QUERY', { cat: 'sql-dialect', name: 'Flashback query / versions / table', re: /\bAS\s+OF\s+(?:TIMESTAMP|SCN)\b|\bVERSIONS\s+BETWEEN\b|\bFLASHBACK\s+TABLE\b|\bDBMS_FLASHBACK\b/, cls: 'REVIEW', w: 12, tag: 'semantic', pg: 'No AS OF. Point-in-time restore is a server operation that creates a new server. Row history needs history tables (temporal_tables is on the allow-list) or audit triggers', ext: 'temporal_tables', why: 'An application that reads past data through AS OF needs a data-model change, not a conversion.' });
e('SQL-WITH-FUNCTION', { cat: 'sql-dialect', name: 'WITH FUNCTION (inline PL/SQL in SQL)', re: /\bWITH\s+(?:FUNCTION|PROCEDURE)\b/, cls: 'REVIEW', w: 4, pg: 'Create a real function', why: 'PostgreSQL cannot declare a function inside a query.' });
e('SQL-HINT', { cat: 'sql-dialect', name: 'Optimizer hints', re: /\/\*\+[\s\S]*?\*\/|--\+[^\n]*/, view: 'raw', cls: 'PARTIAL', w: 0.3, tag: 'perf', pg: 'Ignored by PostgreSQL. pg_hint_plan is available if a plan must be forced', ext: 'pg_hint_plan', affects: false, why: 'Hints are comments to PostgreSQL. The plans they forced are gone, so the queries need performance testing.' });
e('SQL-FOR-UPDATE-WAIT', { cat: 'sql-dialect', name: 'FOR UPDATE WAIT n', re: /\bFOR\s+UPDATE\b[^;]{0,80}\bWAIT\s+\d+\b/, cls: 'REVIEW', w: 2, pg: 'NOWAIT or SKIP LOCKED, with lock_timeout for a bounded wait' });
e('SQL-SAMPLE', { cat: 'sql-dialect', name: 'SAMPLE clause', re: /\bSAMPLE\s*(?:BLOCK\s*)?\(\s*\d/, cls: 'PARTIAL', w: 1, pg: 'TABLESAMPLE BERNOULLI | SYSTEM' });
e('SQL-RETURNING-BULK', { cat: 'sql-dialect', name: 'RETURNING ... BULK COLLECT INTO', re: /\bRETURNING\b[^;]{0,200}\bBULK\s+COLLECT\s+INTO\b/, cls: 'REVIEW', w: 3, lab: 'H-10', pg: 'RETURNING into an array via a CTE, or a loop' });
e('SQL-LOG-ERRORS', { cat: 'sql-dialect', name: 'DML error logging (LOG ERRORS INTO)', re: /\bLOG\s+ERRORS\s+(?:INTO|\()/, cls: 'REVIEW', w: 6, pg: 'None. Row-by-row loop with an EXCEPTION block', why: 'One failing row aborts the whole statement in PostgreSQL.' });
e('SQL-APPROX-FUNCS', { cat: 'sql-dialect', name: 'APPROX_* aggregates', re: /\bAPPROX_(?:COUNT_DISTINCT|MEDIAN|PERCENTILE)\w*\b/, cls: 'REVIEW', w: 2, pg: 'Exact aggregates, or the hll extension for distinct counts' });
e('SQL-APPLY', { cat: 'sql-dialect', name: 'CROSS / OUTER APPLY', re: /\b(?:CROSS|OUTER)\s+APPLY\b/, cls: 'CLEAN', w: 1, pg: 'LATERAL', affects: false });
e('SQL-ENDIAN-ROWID-PSEUDO', { cat: 'sql-dialect', name: 'ROWID / UROWID', re: /\b(?:ROWID|UROWID)\b/, cls: 'REVIEW', w: 2, origin: 'ora2pg-25.0:ROWID', tag: 'semantic', pg: 'A primary key. ctid is not stable across updates or VACUUM FULL', why: 'Code that updates or deletes by ROWID needs a real key.' });
e('SQL-ORA-ROWSCN', { cat: 'sql-dialect', name: 'ORA_ROWSCN', re: /\bORA_ROWSCN\b/, cls: 'REVIEW', w: 3, origin: 'ora2pg-25.0:ORA_ROWSCN', pg: 'xmin as an approximation, or an explicit version column' });
